<?php
namespace Tests\Feature\Configuration;
use App\Models\{Menu,Permission,Role,RoleMenuPermission,User}; use Database\Seeders\SecuritySeeder; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SecurityConfigurationTest extends TestCase { use RefreshDatabase; public function test_admin_can_change_role_menu_permission_matrix(): void {$this->seed(SecuritySeeder::class);$admin=User::where('email','admin@erp.local')->firstOrFail();$role=Role::create(['code'=>'FINANCE','name'=>'Finance','is_active'=>true]);$menu=Menu::where('code','master.items')->firstOrFail();$permission=Permission::where('code','view')->firstOrFail();$this->actingAs($admin)->put('/configuration/menu-security/'.$role->id,['grants'=>[$menu->id.':'.$permission->id]])->assertRedirect();$this->assertDatabaseHas('role_menu_permissions',['role_id'=>$role->id,'menu_id'=>$menu->id,'permission_id'=>$permission->id]);$this->assertDatabaseHas('activity_logs',['module'=>'config.menu-security','action'=>'update']);} }
